macros.exemplo:
// The spreadsheet is `sheet`. Ctrl+Enter runs; Ctrl+Z undoes the whole macro.
// Every function, with examples: "Guide" button.

// 1) Read and write
sheet.set("F1", "Report");
sheet.log("A1 is:", sheet.value("A1"));

// 2) Work with a range
sheet.range("A1:D1").style({ bold: true });

// 3) Fill with a loop
for (let row = 2; row <= 6; row++) {
  sheet.set("F" + row, "=D" + row + "*0.1");
}

// 4) Create a function to use in cells: =TAX(D2)
sheet.defineFunction("TAX", (value) => value * 0.15);

